// fakeBinding is one canned module binding the test's PluginConfigs fake
// flattens into the closure's parallel slices (the cmd-side shape).
type fakeBinding struct {
	moduleID      string
	kind          string
	priority      int
	enabled       bool
	authMode      string
	displayFields string // raw JSON, "" undeclared
	options       string // raw JSON, "" undeclared
}

// fakePluginConfigs builds a Deps.PluginConfigs closure over the canned
// bindings (the cmd-side registry walk, frozen in the test): an id absent
// from the map is unknown (the ErrUnknownPlugin contract).
func fakePluginConfigs(byPlugin map[string][]fakeBinding) func(context.Context, string) ([]string, []string, []int, []bool, []string, []string, []string, error) {
	return func(_ context.Context, pluginID string) ([]string, []string, []int, []bool, []string, []string, []string, error) {
		rows, ok := byPlugin[pluginID]
		if !ok {
			return nil, nil, nil, nil, nil, nil, nil, fmt.Errorf("plugin configs %q: %w", pluginID, ErrUnknownPlugin)
		}
		mids := make([]string, 0, len(rows))
		kinds := make([]string, 0, len(rows))
		priorities := make([]int, 0, len(rows))
		enableds := make([]bool, 0, len(rows))
		auths := make([]string, 0, len(rows))
		fields := make([]string, 0, len(rows))
		options := make([]string, 0, len(rows))
		for _, b := range rows {
			mids = append(mids, b.moduleID)
			kinds = append(kinds, b.kind)
			priorities = append(priorities, b.priority)
			enableds = append(enableds, b.enabled)
			auths = append(auths, b.authMode)
			fields = append(fields, b.displayFields)
			options = append(options, b.options)
		}
		return mids, kinds, priorities, enableds, auths, fields, options, nil
	}
}

