// pluginByID indexes the decoded aggregate by plugin id, failing on a wrong
// row count or order (boot order is part of the contract).
func pluginByID(t *testing.T, got pluginAdminResponse, wantOrder []string) map[string]pluginAdminPlugin {
	t.Helper()
	if len(got.Plugins) != len(wantOrder) {
		t.Fatalf("plugins = %d rows, want %d", len(got.Plugins), len(wantOrder))
	}
	byID := make(map[string]pluginAdminPlugin, len(got.Plugins))
	for i, p := range got.Plugins {
		if p.PluginID != wantOrder[i] {
			t.Fatalf("plugins[%d] = %s, want %s (boot order)", i, p.PluginID, wantOrder[i])
		}
		byID[p.PluginID] = p
	}
	return byID
}

// TestAdminPlugins is the plugin-admin aggregate joint test (api side; the
// scenarios behind probe ff293933e074fc83 / dba497c843f5b188): GET
// /admin/plugins assembles the boot inventory, health, capability chips,
// module-scope effective verdicts, and config bindings — read-only.
func TestAdminPlugins(t *testing.T) {
	t.Run("aggregate_carries_scanner_and_metadata_plugins_with_config", func(t *testing.T) {
		h := pluginsFixture(t)
		got := fetchAdminPlugins(t, h)
		byID := pluginByID(t, got, []string{"serial-scanner", "serial-parser", "frame-grabber", "shikimori"})

		sh := byID["shikimori"]
		if sh.Name != "Shikimori" || sh.Description != "External Shikimori metadata enrichment for serials." {
			t.Fatalf("shikimori identity = %q/%q, want the boot literals", sh.Name, sh.Description)
		}
		if sh.Health == nil || sh.Health.State != "serving" || sh.Health.Restarts != 1 ||
			sh.Health.CheckedAt != "2026-10-20T00:00:00Z" {
			t.Fatalf("shikimori health = %+v, want the serving snapshot", sh.Health)
		}
		if len(sh.Capabilities) != 1 || sh.Capabilities[0] != "metadata_source" {
			t.Fatalf("shikimori capabilities = %v, want [metadata_source]", sh.Capabilities)
		}
		if sh.Effective == nil || len(sh.Effective.Modules) != 1 || sh.Effective.Modules["serial"] {
			t.Fatalf("shikimori effective = %+v, want {serial: false} (module gate mutes)", sh.Effective)
		}
		wantSh := pluginAdminBinding{ModuleID: "serial", Kind: "metadata", Priority: intPtr(3),
			Enabled: boolPtr(true), AuthMode: "NONE",
			DisplayFields: json.RawMessage(`["title","year"]`),
			Options:       json.RawMessage(`{"base_url":"https://shikimori.one"}`)}
		if len(sh.Config) != 1 || sh.Config[0].ModuleID != wantSh.ModuleID ||
			sh.Config[0].Kind != wantSh.Kind || sh.Config[0].AuthMode != wantSh.AuthMode ||
			*sh.Config[0].Priority != *wantSh.Priority || *sh.Config[0].Enabled != *wantSh.Enabled ||
			string(sh.Config[0].DisplayFields) != string(wantSh.DisplayFields) ||
			string(sh.Config[0].Options) != string(wantSh.Options) {
			t.Fatalf("shikimori config = %+v, want %+v (options verbatim)", sh.Config, wantSh)
		}

		sc := byID["serial-scanner"]
		if sc.Health != nil {
			t.Fatalf("serial-scanner health = %+v, want none (not in the snapshot)", sc.Health)
		}
		if sc.Effective != nil {
			t.Fatalf("serial-scanner effective = %+v, want absent (no metadata binding)", sc.Effective)
		}
		if len(sc.Config) != 1 || sc.Config[0].Kind != "scanner" || sc.Config[0].Priority != nil ||
			sc.Config[0].Enabled != nil || sc.Config[0].AuthMode != "" || sc.Config[0].DisplayFields != nil ||
			string(sc.Config[0].Options) != `{"structure":"serial"}` {
			t.Fatalf("serial-scanner config = %+v, want a scanner row with options only", sc.Config)
		}
		if !byID["serial-parser"].Effective.Modules["serial"] || !byID["frame-grabber"].Effective.Modules["serial"] {
			t.Fatalf("local parsers effective = %+v/%+v, want enabled",
				byID["serial-parser"].Effective, byID["frame-grabber"].Effective)
		}
	})

	t.Run("aggregate_writes_nothing", func(t *testing.T) {
		st := openAPIStore(t)
		ctx := context.Background()
		if err := st.UpsertMetadataSourcePref(ctx, store.MetadataSourcePref{
			ModuleID: "serial", PluginID: "shikimori", Enabled: false,
		}); err != nil {
			t.Fatalf("upsert pref: %v", err)
		}
		before, err := st.ListMetadataSourcePrefs(ctx, "serial", nil)
		if err != nil {
			t.Fatalf("list prefs: %v", err)
		}
		h := New(Deps{
			AdminToken: adminToken, Store: st,
			SourceInventory: func(context.Context) ([]string, map[string]string, map[string]string) {
				return []string{"shikimori"}, nil, nil
			},
			ModuleIDs: func(context.Context) ([]string, error) { return []string{"serial"}, nil },
			ModuleSources: fakeModuleSources(st, map[string][]fakeChain{
				"serial": {{pluginID: "shikimori", priority: 3, configEnabled: true}},
			}),
			PluginConfigs: fakePluginConfigs(map[string][]fakeBinding{
				"shikimori": {{moduleID: "serial", kind: "metadata", priority: 3, enabled: true}},
			}),
		})
		fetchAdminPlugins(t, h)
		after, err := st.ListMetadataSourcePrefs(ctx, "serial", nil)
		if err != nil {
			t.Fatalf("list prefs: %v", err)
		}
		if len(before) != len(after) {
			t.Fatalf("prefs rows %d -> %d, want unchanged (read-only aggregate)", len(before), len(after))
		}
	})

	t.Run("client_role_is_forbidden", func(t *testing.T) {
		h := gatingRouter(Deps{AdminToken: adminToken, Store: openAPIStore(t)}, RoleClient)
		resp := doRequest(t, h, http.MethodGet, "/api/v1/admin/plugins", "", "")
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusForbidden {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusForbidden)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "forbidden" {
			t.Fatalf("error code = %q, want forbidden (the admin-group role error)", eb.Error.Code)
		}
	})

	t.Run("nil_closures_return_503", func(t *testing.T) {
		h := New(Deps{AdminToken: adminToken, Store: openAPIStore(t)})
		resp := doRequest(t, h, http.MethodGet, "/api/v1/admin/plugins", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusServiceUnavailable {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusServiceUnavailable)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "unavailable" {
			t.Fatalf("error code = %q, want unavailable", eb.Error.Code)
		}
	})

	t.Run("closure_error_is_500", func(t *testing.T) {
		h := New(Deps{
			AdminToken: adminToken, Store: openAPIStore(t),
			SourceInventory: func(context.Context) ([]string, map[string]string, map[string]string) {
				return []string{"shikimori"}, nil, nil
			},
			ModuleIDs:     func(context.Context) ([]string, error) { return []string{"serial"}, nil },
			ModuleSources: fakeModuleSources(openAPIStore(t), map[string][]fakeChain{}),
			PluginConfigs: func(context.Context, string) ([]string, []string, []int, []bool, []string, []string, []string, error) {
				return nil, nil, nil, nil, nil, nil, nil, fmt.Errorf("registry boom")
			},
		})
		resp := doRequest(t, h, http.MethodGet, "/api/v1/admin/plugins", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusInternalServerError {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusInternalServerError)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "internal_error" {
			t.Fatalf("error code = %q, want internal_error", eb.Error.Code)
		}
	})
}

// TestAdminPluginLogs is the logs endpoint joint test (api side; the
// scenarios behind probe 35c9a9d6a5f1aa67 / c0f06700ef3126b6): the tail
// serves oldest-first under the plugin's id; unknown → 400; nil → 503;
// closure error → 500; admin-gated like the aggregate.
func TestAdminPluginLogs(t *testing.T) {
	t.Run("serves_the_captured_tail_oldest_first", func(t *testing.T) {
		h := pluginsFixture(t)
		resp := doRequest(t, h, http.MethodGet, "/api/v1/admin/plugins/shikimori/logs", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		var out pluginLogsResponse
		if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
			t.Fatalf("decode pluginLogsResponse: %v", err)
		}
		if out.PluginID != "shikimori" || len(out.Lines) != 2 ||
			out.Lines[0] != "first line" || out.Lines[1] != "second line" {
			t.Fatalf("logs = %+v, want shikimori's tail oldest-first", out)
		}
	})

	t.Run("unknown_plugin_is_400", func(t *testing.T) {
		h := New(Deps{
			AdminToken: adminToken, Store: openAPIStore(t),
			PluginLogs: func(_ context.Context, pluginID string) ([]string, error) {
				return nil, fmt.Errorf("plugin logs %q: %w", pluginID, ErrUnknownPlugin)
			},
		})
		resp := doRequest(t, h, http.MethodGet, "/api/v1/admin/plugins/nope/logs", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusBadRequest {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusBadRequest)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "bad_request" {
			t.Fatalf("error code = %q, want bad_request", eb.Error.Code)
		}
	})

	t.Run("nil_closure_is_503_and_closure_error_is_500", func(t *testing.T) {
		nilH := New(Deps{AdminToken: adminToken, Store: openAPIStore(t)})
		resp := doRequest(t, nilH, http.MethodGet, "/api/v1/admin/plugins/x/logs", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusServiceUnavailable {
			t.Fatalf("nil closure status = %d, want %d", resp.StatusCode, http.StatusServiceUnavailable)
		}
		errH := New(Deps{
			AdminToken: adminToken, Store: openAPIStore(t),
			PluginLogs: func(context.Context, string) ([]string, error) {
				return nil, fmt.Errorf("manager boom")
			},
		})
		resp = doRequest(t, errH, http.MethodGet, "/api/v1/admin/plugins/x/logs", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusInternalServerError {
			t.Fatalf("closure error status = %d, want %d", resp.StatusCode, http.StatusInternalServerError)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "internal_error" {
			t.Fatalf("error code = %q, want internal_error", eb.Error.Code)
		}
	})

	t.Run("client_role_is_forbidden", func(t *testing.T) {
		h := gatingRouter(Deps{AdminToken: adminToken, Store: openAPIStore(t)}, RoleClient)
		resp := doRequest(t, h, http.MethodGet, "/api/v1/admin/plugins/x/logs", "", "")
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusForbidden {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusForbidden)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "forbidden" {
			t.Fatalf("error code = %q, want forbidden (the admin-group role error)", eb.Error.Code)
		}
	})
}

